from __future__ import annotations

import json
import os
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Dict, Mapping, Optional

import requests


DEFAULT_API_BASE_URL = "https://api.openai.com/v1"
DEFAULT_MODEL = "gpt-5.4-mini"


def _load_json_file(path: Path) -> Dict[str, Any]:
    if not path.exists():
        return {}
    with path.open("r", encoding="utf-8") as f:
        data = json.load(f)
    return data if isinstance(data, dict) else {}


def _first_nonempty(*values: Optional[str]) -> Optional[str]:
    for value in values:
        if value is not None and str(value).strip():
            return str(value).strip()
    return None


@dataclass(frozen=True)
class DocumentClientConfig:
    api_key: str
    api_base_url: str = DEFAULT_API_BASE_URL
    model: str = DEFAULT_MODEL
    timeout_seconds: float = 60.0

    @classmethod
    def from_env(cls) -> "DocumentClientConfig":
        config_path = os.getenv("DOCUMENT_EXTRACTION_CONFIG")
        file_config: Dict[str, Any] = _load_json_file(Path(config_path)) if config_path else {}

        api_key = _first_nonempty(
            os.getenv("OPENAI_API_KEY"),
            os.getenv("DOCUMENT_EXTRACTION_API_KEY"),
            file_config.get("api_key"),
        )
        if not api_key:
            raise ValueError("Missing API key: set OPENAI_API_KEY or DOCUMENT_EXTRACTION_API_KEY")

        api_base_url = _first_nonempty(
            os.getenv("OPENAI_BASE_URL"),
            os.getenv("DOCUMENT_EXTRACTION_API_BASE_URL"),
            file_config.get("api_base_url"),
            DEFAULT_API_BASE_URL,
        ) or DEFAULT_API_BASE_URL

        model = _first_nonempty(
            os.getenv("DOCUMENT_EXTRACTION_MODEL"),
            file_config.get("model"),
            DEFAULT_MODEL,
        ) or DEFAULT_MODEL

        timeout_raw = _first_nonempty(
            os.getenv("DOCUMENT_EXTRACTION_TIMEOUT"),
            file_config.get("timeout_seconds"),
        )
        timeout_seconds = float(timeout_raw) if timeout_raw else 60.0

        return cls(api_key=api_key, api_base_url=api_base_url.rstrip("/"), model=model, timeout_seconds=timeout_seconds)


class DocumentClient:
    def __init__(self, config: Optional[DocumentClientConfig] = None) -> None:
        self.config = config or DocumentClientConfig.from_env()
        self._session = requests.Session()
        self._session.headers.update(
            {
                "Authorization": f"Bearer {self.config.api_key}",
                "Content-Type": "application/json",
            }
        )

    def close(self) -> None:
        self._session.close()

    def __enter__(self) -> "DocumentClient":
        return self

    def __exit__(self, exc_type, exc, tb) -> None:
        self.close()

    def request(self, payload: Mapping[str, Any], *, endpoint: str = "/responses") -> Dict[str, Any]:
        url = f"{self.config.api_base_url}{endpoint}"
        body = dict(payload)
        body.setdefault("model", self.config.model)
        response = self._session.post(url, json=body, timeout=self.config.timeout_seconds)
        response.raise_for_status()
        return response.json()


def get_document_client(config: Optional[DocumentClientConfig] = None) -> DocumentClient:
    return DocumentClient(config=config)


def load_local_config(path: Optional[str] = None) -> Dict[str, Any]:
    config_path = Path(path or os.getenv("DOCUMENT_EXTRACTION_CONFIG", "")).expanduser()
    return _load_json_file(config_path) if str(config_path) else {}


def normalize_response_text(response: Mapping[str, Any]) -> str:
    if "output_text" in response and isinstance(response["output_text"], str):
        return response["output_text"]
    output = response.get("output")
    if isinstance(output, list):
        chunks = []
        for item in output:
            if isinstance(item, Mapping):
                content = item.get("content")
                if isinstance(content, list):
                    for part in content:
                        if isinstance(part, Mapping) and isinstance(part.get("text"), str):
                            chunks.append(part["text"])
        return "".join(chunks)
    return ""

import json
import os
from typing import Any, Dict, Optional

import requests


OPENAI_API_BASE = os.getenv("OPENAI_API_BASE", "https://api.openai.com/v1")
OPENAI_API_KEY = os.getenv("OPENAI_API_KEY")
OPENAI_MODEL = os.getenv("OPENAI_MODEL", "gpt-5.4-mini")


def _coerce_float(value: Any) -> Optional[float]:
    if value is None:
        return None
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, str):
        text = value.strip().replace(",", "")
        if not text:
            return None
        try:
            return float(text)
        except ValueError:
            return None
    return None


def _standardize_items(items: Any) -> list:
    if not isinstance(items, list):
        return []
    normalized = []
    for item in items:
        if not isinstance(item, dict):
            continue
        normalized.append(
            {
                "description": item.get("description") or item.get("name") or item.get("title"),
                "quantity": _coerce_float(item.get("quantity")) or 1.0,
                "unit_price": _coerce_float(item.get("unit_price") or item.get("price")),
                "amount": _coerce_float(item.get("amount") or item.get("total")),
            }
        )
    return normalized


def _local_normalize(expense: Dict[str, Any]) -> Dict[str, Any]:
    return {
        "provider": "openai",
        "model": OPENAI_MODEL,
        "currency": expense.get("currency") or expense.get("currency_code") or "USD",
        "merchant": expense.get("merchant") or expense.get("vendor") or expense.get("payee"),
        "date": expense.get("date") or expense.get("transaction_date") or expense.get("receipt_date"),
        "subtotal": _coerce_float(expense.get("subtotal")),
        "tax": _coerce_float(expense.get("tax") or expense.get("tax_amount")),
        "tip": _coerce_float(expense.get("tip") or expense.get("gratuity")),
        "total": _coerce_float(expense.get("total") or expense.get("amount") or expense.get("grand_total")),
        "notes": expense.get("notes") or expense.get("memo") or expense.get("description"),
        "items": _standardize_items(expense.get("items") or expense.get("line_items")),
    }


def _remote_normalize(expense: Dict[str, Any]) -> Dict[str, Any]:
    if not OPENAI_API_KEY:
        raise RuntimeError("OPENAI_API_KEY is required for remote normalization")

    schema = {
        "name": "expense_normalization",
        "schema": {
            "type": "object",
            "properties": {
                "provider": {"type": "string"},
                "model": {"type": "string"},
                "currency": {"type": ["string", "null"]},
                "merchant": {"type": ["string", "null"]},
                "date": {"type": ["string", "null"]},
                "subtotal": {"type": ["number", "null"]},
                "tax": {"type": ["number", "null"]},
                "tip": {"type": ["number", "null"]},
                "total": {"type": ["number", "null"]},
                "notes": {"type": ["string", "null"]},
                "items": {
                    "type": "array",
                    "items": {
                        "type": "object",
                        "properties": {
                            "description": {"type": ["string", "null"]},
                            "quantity": {"type": ["number", "null"]},
                            "unit_price": {"type": ["number", "null"]},
                            "amount": {"type": ["number", "null"]},
                        },
                        "required": ["description", "quantity", "unit_price", "amount"],
                        "additionalProperties": False,
                    },
                },
            },
            "required": ["provider", "model", "currency", "merchant", "date", "subtotal", "tax", "tip", "total", "notes", "items"],
            "additionalProperties": False,
        },
    }

    response = requests.post(
        f"{OPENAI_API_BASE}/responses",
        headers={
            "Authorization": f"Bearer {OPENAI_API_KEY}",
            "Content-Type": "application/json",
        },
        json={
            "model": OPENAI_MODEL,
            "input": [
                {
                    "role": "system",
                    "content": "Normalize expense extraction into a standard JSON schema.",
                },
                {
                    "role": "user",
                    "content": json.dumps(expense, ensure_ascii=False),
                },
            ],
            "response_format": {"type": "json_schema", "json_schema": schema},
        },
        timeout=60,
    )
    response.raise_for_status()
    data = response.json()
    text = data.get("output_text")
    if text:
        return json.loads(text)
    output = data.get("output", [])
    for item in output:
        for content in item.get("content", []):
            if content.get("type") == "output_text":
                return json.loads(content.get("text", "{}"))
    raise RuntimeError("OpenAI normalization response did not contain JSON output")


def normalize_expense(expense: Dict[str, Any], use_remote: bool = False) -> Dict[str, Any]:
    if use_remote:
        return _remote_normalize(expense)
    return _local_normalize(expense)

